def permutation_rank(perm):
    n = len(perm)
    rank = 0
    for i in range(n):
        cnt = 0
        for j in range(i+1, n):
            if perm[j] < perm[i]:
                cnt += 1
        f = 1
        for k in range(2, n - i):
            f *= k
        rank += cnt * f
    return rank
